101	    traced: Tracked<Traced>,
102	    sink: &mut Sink,
103	) -> SourceResult<T> {
104	    let library = world.library();
105	    match T::target() {
106	        Target::Paged => {}
107	        Target::Html => warn_or_error_for_html(&library.features, sink)?,
108	        Target::Bundle => warn_or_error_for_bundle(&library.features, sink)?,
